+func withShapeIndexCRC(payload []byte) []byte {
+	out := make([]byte, len(payload)+4)
+	copy(out, payload)
+	binary.LittleEndian.PutUint32(out[len(payload):], crc32.ChecksumIEEE(payload))
+	return out
+}
+
+func appendUvarint(b []byte, v uint64) []byte {
+	var tmp [binary.MaxVarintLen64]byte
+	n := binary.PutUvarint(tmp[:], v)
+	return append(b, tmp[:n]...)
+}
+
+func appendUint64LE(b []byte, v uint64) []byte {
+	var tmp [8]byte
+	binary.LittleEndian.PutUint64(tmp[:], v)
+	return append(b, tmp[:]...)
+}
+
+func appendUint32LE(b []byte, v uint32) []byte {
+	var tmp [4]byte
+	binary.LittleEndian.PutUint32(tmp[:], v)
+	return append(b, tmp[:]...)
+}
+
+func appendFloat64LE(b []byte, f float64) []byte {
+	return appendUint64LE(b, math.Float64bits(f))
+}
+
+func appendPointLE(b []byte, p Point) []byte {
+	b = appendFloat64LE(b, p.X)
+	b = appendFloat64LE(b, p.Y)
+	b = appendFloat64LE(b, p.Z)
+	return b
+}
